6. GESTURE STATE MACHINE (pointer events, complete)
══════════════════════════════════════════════════════
const SLOP = 10;    // CSS px — below this a move is still a tap
const TAP  = 250;   // ms
const LONG = 500;   // ms
const ORBIT_K = 0.0055;      // rad per CSS px
const POLAR = [0.35, 1.25];  // rad — stops the camera going under the board
const DOLLY = [2.4, 9.0];    // world units (0.6x - 2.2x of default 4.1)

const P = new Map();   // pointerId -> {x0,y0,px,py,x,y,t0}
let mode = 'idle';     // idle|pending|orbit|piece|inspect|two|settle
let pending = null, longTimer = 0, d0 = 0, mid0 = null, cam0 = null;
const clamp = (v,a,b) => v < a ? a : v > b ? b : v;

gl.addEventListener('pointerdown', e => {
  gl.setPointerCapture(e.pointerId);
  P.set(e.pointerId, { x0:e.clientX, y0:e.clientY, px:e.clientX, py:e.clientY,
                       x:e.clientX,  y:e.clientY,  t0:performance.now() });

  if (P.size === 1) {
    const hit = raycastAt(e.clientX, e.clientY);   // -> {piece?, tile?} | null
    pending = { id:e.pointerId, hit };
    mode = 'pending';
    longTimer = setTimeout(() => {
      if (mode !== 'pending') return;
      mode = 'inspect'; showInspector(hit); navigator.vibrate?.(10);
    }, LONG);
  } else if (P.size === 2) {
    clearTimeout(longTimer);
    if (mode === 'piece') dropPiece(null);        // cancel a half-started drag
    mode = 'two';
    const [a, b] = [...P.values()];
    d0   = Math.hypot(a.x - b.x, a.y - b.y) || 1;
    mid0 = { x:(a.x + b.x) / 2, y:(a.y + b.y) / 2 };
    cam0 = { dist: cam.distance, target: cam.target.clone() };
  } else {
    mode = 'settle';                              // 3+ fingers: do nothing
  }
}, { passive: true });

gl.addEventListener('pointermove', e => {
  const p = P.get(e.pointerId); if (!p) return;
  p.px = p.x; p.py = p.y; p.x = e.clientX; p.y = e.clientY;
  const dx = p.x - p.px, dy = p.y - p.py;

  if (mode === 'pending') {
    if (Math.hypot(p.x - p.x0, p.y - p.y0) <= SLOP) return;
    clearTimeout(longTimer);
    // ---- INTENT LATCHED HERE, ONCE, FOR THE WHOLE GESTURE ----
    mode = (pending.hit?.piece && isMovable(pending.hit.piece)) ? 'piece' : 'orbit';
    if (mode === 'piece') liftPiece(pending.hit.piece);
  }

  if (mode === 'orbit') {
    cam.azimuth -= dx * ORBIT_K;
    cam.polar    = clamp(cam.polar - dy * ORBIT_K, POLAR[0], POLAR[1]);
    invalidate();
  } else if (mode === 'piece') {
    movePieceToScreen(p.x, p.y); invalidate();
  } else if (mode === 'two' && P.size === 2) {
    const [a, b] = [...P.values()];
    const d   = Math.hypot(a.x - b.x, a.y - b.y) || 1;
    const mid = { x:(a.x + b.x) / 2, y:(a.y + b.y) / 2 };
    cam.distance = clamp(cam0.dist * (d0 / d), DOLLY[0], DOLLY[1]);  // pinch = dolly
    panByScreenDelta(mid.x - mid0.x, mid.y - mid0.y, cam0.target);   // centroid = pan
    invalidate();
  }
}, { passive: true });

for (const t of ['pointerup', 'pointercancel']) gl.addEventListener(t, onEnd);
function onEnd(e) {
  const p = P.get(e.pointerId); if (!p) return;
  const dt    = performance.now() - p.t0;
  const moved = Math.hypot(p.x - p.x0, p.y - p.y0);
  P.delete(e.pointerId);
  clearTimeout(longTimer);

  if (e.type === 'pointercancel')            { if (mode === 'piece') dropPiece(null); }
  else if (mode === 'pending' && dt < TAP && moved <= SLOP) selectAt(p.x, p.y);
  else if (mode === 'piece')                 dropPiece(p.x, p.y);
  else if (mode === 'inspect')               hideInspector();

  // Never hand a pinch straight back to orbit — that is the camera-jump bug.
  mode = P.size === 0 ? 'idle' : 'settle';
  invalidate();
}

