import * as THREE from 'three';
THREE.ColorManagement.enabled = true;

const TIERS = {
  high: { dpr: 2.00, aa: true,  shadows: true,  shadowSize: 1024 },
  mid:  { dpr: 1.50, aa: true,  shadows: true,  shadowSize: 512  },
  low:  { dpr: 1.00, aa: false, shadows: false, shadowSize: 0    },
};
let tier = 'mid';   // start mid; promote only after 30s of headroom

const renderer = new THREE.WebGLRenderer({
  canvas: gl,
  antialias: TIERS[tier].aa,  // 4x MSAA resolves in tile memory on Mali/Adreno/Apple
  alpha: false,               // opaque canvas skips per-frame compositing blend
  stencil: false,
  depth: true,
  powerPreference: 'high-performance',
  preserveDrawingBuffer: false,
});
renderer.setPixelRatio(Math.min(devicePixelRatio, TIERS[tier].dpr));
renderer.outputColorSpace     = THREE.SRGBColorSpace;
renderer.toneMapping          = THREE.NoToneMapping;  // ACESFilmic ~0.4ms/frame, Adreno 6xx
renderer.shadowMap.enabled    = TIERS[tier].shadows;
renderer.shadowMap.type       = THREE.PCFShadowMap;   // PCFSoft ~2x cost, invisible at 390px
renderer.shadowMap.autoUpdate = false;                // manual, see invalidateShadows()
renderer.info.autoReset       = false;

// Lighting: exactly two lights. No point lights, ever.
const key = new THREE.DirectionalLight(0xFFF4E2, 2.1);
key.position.set(4, 7, 3);
key.castShadow = true;
key.shadow.mapSize.set(1024, 1024);
Object.assign(key.shadow.camera, { left:-5, right:5, top:5, bottom:-5, near:1, far:16 });
key.shadow.bias = -0.0012; key.shadow.normalBias = 0.02;
scene.add(key, new THREE.HemisphereLight(0x8FB4FF, 0x121722, 0.85));

