9. THERMAL / ADAPTIVE QUALITY
══════════════════════════════════════════════════════
let ema = 16.7, last = 0, changedAt = 0;
function sampleFrame(t) {
  if (last) ema = ema * 0.90 + Math.min(t - last, 100) * 0.10;
  last = t;
  const now = performance.now();
  if (now - changedAt < 4000) return;
  if (ema > 22 && tier !== 'low') {                        // <45fps sustained 2s+
    setTier(tier === 'high' ? 'mid' : 'low'); changedAt = now;
  } else if (ema < 13 && tier !== 'high' && now - changedAt > 30000) {
    setTier(tier === 'low' ? 'mid' : 'high'); changedAt = now;
  }
}
function setTier(next) {
  tier = next; const T = TIERS[next];
  renderer.setPixelRatio(Math.min(devicePixelRatio, T.dpr));
  renderer.shadowMap.enabled = T.shadows;
  key.castShadow = T.shadows;
  if (T.shadows && key.shadow.mapSize.x !== T.shadowSize) {
    key.shadow.mapSize.set(T.shadowSize, T.shadowSize);
    key.shadow.map?.dispose(); key.shadow.map = null;
  }
  invalidateShadows();
}
Degradation order (never reorder): DPR -> shadow resolution -> shadows off
-> AA off -> piece LOD swap. Never below DPR 1.0. Never promote more than
one tier per 30 s — hysteresis stops oscillation on a hot device.

