11. ORIENTATION: FIT A SQUARE-ISH BOARD, BOTH WAYS
══════════════════════════════════════════════════════
function fitDistance(camera, boardRadius, aspect, pad = 1.12) {
  const vFov = THREE.MathUtils.degToRad(camera.fov);
  const hFov = 2 * Math.atan(Math.tan(vFov / 2) * aspect);
  const fov  = Math.min(vFov, hFov);       // the tighter axis always wins
  return (boardRadius * pad) / Math.sin(fov / 2);
}

let rzT;
new ResizeObserver(([entry]) => {
  const { inlineSize: w, blockSize: h } = entry.contentBoxSize[0];
  clearTimeout(rzT);
  rzT = setTimeout(() => {
    renderer.setSize(w, h, false);
    camera.aspect = w / h;
    const portrait = h >= w;
    // Lift the board above the thumb bar in portrait (6% of height).
    camera.setViewOffset(w, h, 0, portrait ? -h * 0.06 : 0, w, h);
    camera.updateProjectionMatrix();
    tweens.to(cam, { distance: fitDistance(camera, BOARD_R, w / h) },
              prefersReducedMotion() ? 0 : 250, 'easeOutCubic');
    invalidateShadows();
  }, 120);
}).observe(document.getElementById('hud'));

Portrait  390x844 -> aspect 0.462, hFov tighter, distance ~= 7.4 units
Landscape 844x390 -> aspect 2.164, vFov tighter, distance ~= 4.1 units
No rotation lock, no interstitial. Both orientations are first-class.

