// Audio: created inside a gesture, and OFF by default for shared links.
let audioCtx = null;
function unlockAudio() {
  if (audioCtx) return;
  audioCtx = new (window.AudioContext || window.webkitAudioContext)();
  const s = audioCtx.createBufferSource();
  s.buffer = audioCtx.createBuffer(1, 1, 22050);
  s.connect(audioCtx.destination); s.start(0);
  audioCtx.resume();
}
gl.addEventListener('pointerup', unlockAudio, { once: true });
let soundEnabled = localStorage.getItem('snd') === '1';   // default OFF

// Wake lock AFTER first interaction, never on load.
let wakeLock = null;
gl.addEventListener('pointerup', async () => {
  try { wakeLock = await navigator.wakeLock?.request('screen'); } catch {}
}, { once: true });

